// Lee los parametros de la CAMPANA desde el WEBHOOK (no del Sheet).
const wh=$('Entrada campaña').first().json;
const b=(wh && wh.body && typeof wh.body==='object')?wh.body:{};
const filtros=(b.filtros && typeof b.filtros==='object')?b.filtros:{};
const mensaje=(b.mensaje||'').toString();
const cantidad=(b.cantidad!=null)?parseInt(b.cantidad,10):null;
const batch_size=parseInt(b.batch_size||5,10);
// FAIL-SAFE: solo envia si viene EXPLICITO confirmar_envio=true. Sin eso => modo prueba, nunca envia.
const confirmar=(b.confirmar_envio===true);
const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
const tel57=s=>{let d=(s||'').toString().replace(/\D/g,'');if(d.length===10)d='57'+d;return d;};
const rows=$('Leer Sheet').all().map(i=>i.json).filter(r=>((r['Nombres']||'').toString().trim())||((r['Telefono']||'').toString().trim()));
const tieneFiltros=Object.keys(filtros).length>0;
function match(r){
  if(!tieneFiltros) return false; // FAIL-SAFE: sin filtros no selecciona a nadie
  if(filtros.telefono && tel57(r['Telefono'])!==tel57(filtros.telefono)) return false;
  if(filtros.nombre_contains && !norm((r['Nombres']||'')+' '+(r['Apellidos']||'')).includes(norm(filtros.nombre_contains))) return false;
  if(filtros.estado && norm(r['Estado'])!==norm(filtros.estado)) return false;
  if(filtros.service_type && !norm(r['Tipo de servicio']).startsWith(norm(filtros.service_type))) return false;
  if(filtros.tipo_lead && norm(r['Tipo de Lead'])!==norm(filtros.tipo_lead)) return false;
  return true;
}
let todos=rows.filter(match);
let seleccion=(cantidad!=null?todos.slice(0,cantidad):todos).map(r=>{const primer=(r['Nombres']||'').toString().trim().split(/\s+/)[0]||'';return{telefono:tel57(r['Telefono']),nombre:((r['Nombres']||'')+' '+(r['Apellidos']||'')).trim(),texto:(mensaje||'(sin mensaje)').replace(/\{nombre\}/gi,primer)};});
const enviar=(confirmar===true && mensaje.trim()!=='' && seleccion.length>0);
const num_lotes=Math.ceil(seleccion.length/batch_size)||0;
return [{json:{total_segmento:todos.length,a_enviar:seleccion.length,batch_size,num_lotes,seleccion,confirmar,enviar,nota: enviar?'ENVIARA de verdad':'MODO PRUEBA (no envia)'}}];
